CREATE POLICY "registry_cr_rls_select_873f6ac889ddf5223506af33" ON registry_data."breg_e_asset_placement_a1ec82196d1fb9aa" FOR SELECT USING (jsonb_typeof(NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb) = 'object' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'version' = '1' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'requestEntityId' = 'placement-correction-request' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'contractFingerprint' = 'sha256:46e622aa481907c36ff3792941fe8d7d56e7ed6f56c2d112d4181bf4c58fafce' AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'effectDigest') ~ '^sha256:[0-9a-f]{64}$' AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'actorReference') IS NOT NULL AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'selectedAccessProfile' = 'correction-submitter' AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'selectedAccessProfile') = NULLIF(current_setting('registry.access_profile', true), '') AND ((NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'principal') IS NULL OR (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'principal') = NULLIF(current_setting('registry.principal', true), '')) AND ((NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'purpose') IS NULL OR (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'purpose') = NULLIF(current_setting('registry.purpose', true), '')) AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'effectId' = 'effect-1' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetEntityId' = 'asset-placement' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'operation' = 'patch' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'fields' = '["site"]'::jsonb AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'activePackageRevision' = NULLIF(current_setting('registry.active_package_revision', true), '') AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetRecordId' = "record_id"::text AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'phase' = '{"kind":"preparation"}'::jsonb AND NULLIF(current_setting('registry.access_profile', true), '') = 'correction-submitter' AND NULLIF(current_setting('registry.principal', true), '') IS NOT NULL AND NULLIF(current_setting('registry.purpose', true), '') IN ('asset-correction') AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'targetRowBoundaries' = '[]'::jsonb AND EXISTS (
            SELECT 1
              FROM registry_internal.registry_request_state AS cr_state
             WHERE cr_state.request_entity_id = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'requestEntityId')
               AND cr_state.request_id = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'requestId')::uuid
               AND cr_state.proposal_version = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'proposalVersion')::bigint
               AND cr_state.state = 'draft'
               AND cr_state.owner_reference = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'actorReference')
        ) AND record_lifecycle = 'active');
CREATE POLICY "registry_cr_rls_select_cad186681e91a3c896be6432" ON registry_data."breg_e_asset_placement_a1ec82196d1fb9aa" FOR SELECT USING (jsonb_typeof(NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb) = 'object' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'version' = '1' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'requestEntityId' = 'placement-correction-request' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'contractFingerprint' = 'sha256:46e622aa481907c36ff3792941fe8d7d56e7ed6f56c2d112d4181bf4c58fafce' AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'effectDigest') ~ '^sha256:[0-9a-f]{64}$' AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'actorReference') IS NOT NULL AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'selectedAccessProfile' = 'correction-supervisor' AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'selectedAccessProfile') = NULLIF(current_setting('registry.access_profile', true), '') AND ((NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'principal') IS NULL OR (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'principal') = NULLIF(current_setting('registry.principal', true), '')) AND ((NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'purpose') IS NULL OR (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'purpose') = NULLIF(current_setting('registry.purpose', true), '')) AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'effectId' = 'effect-1' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetEntityId' = 'asset-placement' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'operation' = 'patch' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'fields' = '["site"]'::jsonb AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'activePackageRevision' = NULLIF(current_setting('registry.active_package_revision', true), '') AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetRecordId' = "record_id"::text AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'phase' = '{"kind":"review","stage":"final-approval"}'::jsonb AND NULLIF(current_setting('registry.access_profile', true), '') = 'correction-supervisor' AND NULLIF(current_setting('registry.principal', true), '') IS NOT NULL AND NULLIF(current_setting('registry.purpose', true), '') IN ('asset-correction-review') AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'expectedRevision') IS NOT NULL
         AND EXISTS (
             SELECT 1
               FROM registry_internal.registry_request_state AS cr_state
               JOIN registry_internal.registry_request_proposals AS cr_proposal
                 ON cr_proposal.request_entity_id = cr_state.request_entity_id
                AND cr_proposal.request_id = cr_state.request_id
                AND cr_proposal.proposal_version = cr_state.proposal_version
               JOIN registry_internal.registry_request_targets AS cr_target
                 ON cr_target.request_entity_id = cr_proposal.request_entity_id
                AND cr_target.request_id = cr_proposal.request_id
                AND cr_target.proposal_version = cr_proposal.proposal_version
              WHERE cr_state.request_entity_id = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'requestEntityId')
                AND cr_state.request_id = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'requestId')::uuid
                AND cr_state.proposal_version = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'proposalVersion')::bigint
                AND cr_state.state = 'submitted'
                AND cr_proposal.contract_fingerprint = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'contractFingerprint')
                AND cr_proposal.effect_digest = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'effectDigest')
                AND cr_target.target_entity_id = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetEntityId')
                AND cr_target.target_record_id = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetRecordId')::uuid
                AND cr_target.operation = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'operation')
                AND (
                    (cr_target.expected_revision IS NULL AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'expectedRevision') IS NULL)
                    OR cr_target.expected_revision = (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'expectedRevision')::bigint
